<script setup>
import { computed,ref,watch,onUnmounted,onMounted } from 'vue'
import { adminApi } from '../../../config/factoryConfig.js'
import { permissionDirective as vPermission } from '../../../runtime/pagePermissionUi.js'
import { getFactoryScope } from '../../../runtime/factoryScope.js'
import { cacheFactoryDraft,readFactoryDraft,clearFactoryDraft } from '../../../runtime/factoryDraftCache.js'
import { createDashboardDataStore } from '../../../runtime/DataStore.js'
import { receiveMotionSignal,stepMotionSignal } from '../../../three/PortableMotionPlayer.js'
import MotionLinkPreview from './MotionLinkPreview.vue'
const props=defineProps({devices:{type:Array,default:()=>[]},models:{type:Array,default:()=>[]},confirm:{type:Function,required:true}})
const selectedId=ref(''),query=ref(''),loaded=ref(null),draft=ref(null),busy=ref(false),error=ref(''),message=ref(''),activeId=ref(''),section=ref('bindings'),previewMode=ref('live'),testValue=ref(0),runtime=ref(null)
const factory=getFactoryScope(),states=ref({}),frame=ref(null),points=ref([]),saved=ref(''),store=createDashboardDataStore({staleMs:5000})
let generation=0,disposed=false,frameTime=0,tick
const device=computed(()=>props.devices.find(d=>String(d.id)===selectedId.value)),model=computed(()=>props.models.find(m=>m.id===loaded.value?.modelId))
const options=computed(()=>props.devices.filter(d=>`${d.name} ${d.id}`.toLowerCase().includes(query.value.toLowerCase())))
const dirty=computed(()=>draft.value&&JSON.stringify(draft.value)!==saved.value)
const action=computed(()=>loaded.value?.actions.find(a=>a.id===activeId.value))
const row=computed(()=>draft.value?.bindings.find(b=>b.actionId===activeId.value))
const readPoints=computed(()=>points.value.filter(p=>String(p.access_type||'READ').toUpperCase()==='READ'))
const resolvedBindings=computed(()=>draft.value?.bindings.map(b=>{const a=loaded.value.actions.find(a=>a.id===b.actionId),p=points.value.find(p=>String(p.id)===String(b.pointId));return {...b,kind:a?.kind,mode:a?.mode,clipId:a?.kind==='clip'?a.id.slice(5):'',sourceGroup:p?.category||'analog',sourceKey:p?.value_role||p?.name||''}})||[])
const previewBindings=computed(()=>previewMode.value==='test'&&action.value?[{...resolvedBindings.value.find(b=>b.actionId===activeId.value),enabled:true}]:resolvedBindings.value)
function stateFor(id){return states.value[id]||{reason:'等待数据'}}
function persist(){if(dirty.value&&loaded.value)cacheFactoryDraft(factory,`animation:${selectedId.value}`,'device-animations',{deviceId:selectedId.value,revision:loaded.value.revision,config:draft.value})}
async function canLeave(){return !dirty.value||await props.confirm('动画联动尚未保存，保留草稿并离开？')}
async function choose(id){if(id===selectedId.value||busy.value||!await canLeave())return;persist();selectedId.value=String(id)}
async function load(){const version=++generation;loaded.value=null;draft.value=null;frame.value=null;frameTime=0;states.value={};error.value='';message.value='';if(!selectedId.value)return;busy.value=true
 try{const [data,rows]=await Promise.all([adminApi.getDeviceAnimations(selectedId.value),adminApi.getDataPoints(selectedId.value)]);if(disposed||version!==generation)return;if(data.error||rows.error)throw Error(data.error||rows.error);loaded.value=data;points.value=rows;const config={version:1,staleMs:data.config.staleMs,bindings:data.actions.map(a=>data.config.bindings.find(b=>b.actionId===a.id)||{actionId:a.id,enabled:false,pointId:'',inputMin:0,inputMax:1,invert:false,speed:1,transitionSeconds:a.mode==='position'?1:0})};saved.value=JSON.stringify(config);const cached=readFactoryDraft(factory,`animation:${selectedId.value}`);draft.value=cached?.revision===data.revision?cached.config:config;if(cached&&cached.revision!==data.revision)message.value='配置已变更，旧草稿未覆盖；请重新绑定';activeId.value=data.actions[0]?.id||'';previewMode.value='live'}catch(e){if(version===generation)error.value=e.message}finally{if(version===generation)busy.value=false}}
async function save(){if(!loaded.value||busy.value)return false;busy.value=true;error.value='';message.value='';const version=generation,body={revision:loaded.value.revision,config:JSON.parse(JSON.stringify(draft.value))}
 try{const result=await adminApi.saveDeviceAnimations(selectedId.value,body);if(disposed||version!==generation)return false;if(result.error||!result.success)throw Error(result.error||'保存未确认');loaded.value={...loaded.value,...result};saved.value=JSON.stringify(body.config);clearFactoryDraft(factory,`animation:${selectedId.value}`);message.value='已保存，Unity 自动同步';return true}catch(e){if(version===generation)error.value=e.message;return false}finally{if(version===generation)busy.value=false}}
function selectPoint(){const point=readPoints.value.find(p=>String(p.id)===row.value.pointId);if(point?.data_type==='BOOL'){row.value.inputMin=0;row.value.inputMax=1}}
watch(()=>props.devices.map(d=>String(d.id)),ids=>{if(!ids.includes(selectedId.value))selectedId.value=ids[0]||''},{immediate:true})
watch(selectedId,load,{immediate:true})
watch(draft,()=>{states.value={};persist()},{deep:true})
store.setDeviceDataHandler(data=>{if(String(data.furnace_id)!==selectedId.value)return;frame.value=data;frameTime=performance.now()/1000;for(const b of resolvedBindings.value){if(!b.enabled)continue;const s=states.value[b.actionId]||{seconds:0};receiveMotionSignal(s,b,data,frameTime);states.value[b.actionId]=s}})
onMounted(()=>{store.connect();tick=setInterval(()=>{const now=performance.now()/1000;for(const b of resolvedBindings.value){const s=states.value[b.actionId];if(s)stepMotionSignal(s,b,.2,now,draft.value?.staleMs||5000)}},200)})
onUnmounted(()=>{persist();disposed=true;generation++;clearInterval(tick);store.dispose()})
defineExpose({canLeave,savePending:()=>dirty.value?save():true})
</script>
<template>
<section class="animation-link" aria-label="设备实时动画联动">
 <aside class="link-devices"><header><strong>现场设备</strong><small>{{ devices.length }} 台</small></header><input v-model="query" class="input" placeholder="搜索设备" aria-label="搜索联动设备"><div class="link-device-list"><button v-for="d in options" :key="d.id" type="button" :class="{active:String(d.id)===selectedId}" :disabled="busy" @click="choose(String(d.id))"><strong>{{ d.name||d.id }}</strong><small>{{ models.find(m=>m.id===d.model_type)?.name||d.model_type }}</small></button></div></aside>
 <main class="link-main"><header class="link-heading"><div><h3>{{ device?.name||'选择设备' }}</h3><small>{{ model?.name||loaded?.modelId }}</small></div><span v-if="dirty" class="unsaved">未保存</span><button class="btn" :disabled="busy" @click="load">重新读取</button><button class="btn btn-primary" :disabled="busy||!dirty" v-permission="{page:'model-animations',action:'edit'}" @click="save">{{busy?'处理中…':'保存并同步'}}</button></header>
 <p v-if="error" class="link-error" role="alert">{{error}}</p><p v-if="message" class="link-message" role="status">{{message}}</p>
 <div v-if="loaded&&draft" class="link-content"><section class="link-config"><nav class="link-tabs" aria-label="动画联动设置"><button type="button" :aria-selected="section==='bindings'" @click="section='bindings'">动作绑定</button><button type="button" :aria-selected="section==='health'" @click="section='health'">运行状况</button></nav>
 <template v-if="section==='bindings'"><div class="action-list" aria-label="可绑定动作"><button v-for="a in loaded.actions" :key="a.id" type="button" :class="{active:activeId===a.id}" @click="activeId=a.id"><span>{{a.label}}</span><small>{{draft.bindings.find(b=>b.actionId===a.id)?.enabled?'已启用':'未启用'}}</small></button><p v-if="!loaded.actions.length" class="hint">该型号尚无动作。在“部件动作”中配置模型节点即可。</p></div>
 <div v-if="row" class="binding-fields"><label class="enable-line"><span>{{action.label}}</span><input v-model="row.enabled" type="checkbox" role="switch" aria-label="启用动作联动" v-permission="{page:'model-animations',action:'edit'}"></label><label>采集点位<select v-model="row.pointId" class="input" aria-label="联动采集点位" @change="selectPoint" v-permission="{page:'model-animations',action:'edit'}"><option value="">选择本设备点位</option><option v-for="p in readPoints" :key="p.id" :value="String(p.id)">{{p.label||p.name}} · {{p.unit||p.data_type}}</option></select></label><div class="range-fields"><label>输入下限<input v-model.number="row.inputMin" class="input" type="number" v-permission="{page:'model-animations',action:'edit'}"></label><label>输入上限<input v-model.number="row.inputMax" class="input" type="number" v-permission="{page:'model-animations',action:'edit'}"></label></div><div class="range-fields"><label v-if="action.mode==='position'">过渡（秒）<input v-model.number="row.transitionSeconds" class="input" type="number" min="0" max="60" step=".1" v-permission="{page:'model-animations',action:'edit'}"></label><label v-else>动画速度<input v-model.number="row.speed" class="input" type="number" min=".05" max="10" step=".1" v-permission="{page:'model-animations',action:'edit'}"></label><label>方向<select v-model="row.invert" class="input" v-permission="{page:'model-animations',action:'edit'}"><option :value="false">正常</option><option :value="true">反向</option></select></label></div><small class="hint">{{action.mode==='position'?'输入范围映射到动作行程。':'信号高于输入范围中点时运行。'}} 仅驱动画面，不写入 PLC。</small></div></template>
 <template v-else><label class="timeout">无新数据暂停（毫秒）<input v-model.number="draft.staleMs" class="input" type="number" min="1000" max="60000" v-permission="{page:'model-animations',action:'edit'}"></label><div class="health-list"><article v-for="b in draft.bindings.filter(b=>b.enabled)" :key="b.actionId"><strong>{{loaded.actions.find(a=>a.id===b.actionId)?.label}}</strong><span :class="{good:stateFor(b.actionId).usable}">{{stateFor(b.actionId).reason}}</span><small>{{points.find(p=>String(p.id)===b.pointId)?.label||points.find(p=>String(p.id)===b.pointId)?.name||'点位已删除'}}</small></article><p v-if="!draft.bindings.some(b=>b.enabled)" class="hint">尚未启用动作</p></div></template>
 </section><section class="link-preview"><header><div class="link-tabs"><button type="button" :aria-selected="previewMode==='live'" @click="previewMode='live'">跟随采集</button><button type="button" :aria-selected="previewMode==='test'" @click="previewMode='test'">本页试动作</button></div><small>{{previewMode==='live'?'采集数据驱动画面':'仅本页，不影响大屏及 PLC'}}</small></header><MotionLinkPreview :key="selectedId+':'+loaded.revision" :model="model" :bundle="loaded.motionPackage" :bindings="previewBindings" :points="points" :frame="frame" :frame-time="frameTime" :stale-ms="draft.staleMs" :test="previewMode==='test'" :test-value="testValue" @ready="runtime=$event"/><footer v-if="previewMode==='test'&&action"><label>{{action.mode==='position'?'行程':'运行信号'}}<input v-model.number="testValue" type="range" min="0" max="1" step=".01" aria-label="试动作进度"><span>{{Math.round(testValue*100)}}%</span></label></footer><footer v-else><span :class="{good:store.wsConnected.value}">{{store.wsConnected.value?'数据已连接':'等待数据连接'}}</span><small>保存后在 Unity 大屏生效</small></footer></section></div>
 <p v-else-if="busy" class="hint">正在读取动作与点位…</p>
 </main>
</section>
</template>
<style scoped>
