r:#8190a4;white-space:nowrap;font-size:10px}.binding-fields{display:grid;gap:12px;border-top:1px solid #e5eaf1;padding-top:13px;font-size:12px}.binding-fields label,.timeout{display:grid;gap:7px;min-width:0}.enable-line{display:flex!important;align-items:center;justify-content:space-between;font-weight:600}.enable-line input{appearance:none;width:36px;height:21px;border-radius:20px;background:#c2cad6;position:relative;cursor:pointer;transition:background .15s}.enable-line input:before{content:'';position:absolute;width:15px;height:15px;left:3px;top:3px;border-radius:50%;background:white;transition:transform .15s}.enable-line input:checked{background:#428de0}.enable-line input:checked:before{transform:translateX(15px)}.range-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.hint{color:#8591a3;font-size:11px;line-height:1.6}.input{box-sizing:border-box;width:100%;padding:9px 10px;font:inherit;font-size:12px;border:1px solid #d4dce8;border-radius:7px;background:#fafbfe;color:#32455b}.input:focus-visible{outline:2px solid #a6c7ff}.link-preview{display:flex;flex-direction:column;min-width:0;background:#f5f7fa}.link-preview>header{padding:12px;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.link-preview header small{color:#8b95a4;font-size:10px}.link-preview footer{padding:13px;display:flex;justify-content:space-between;align-items:center;color:#7a889b;font-size:11px;background:white}.link-preview footer label{width:100%;display:flex;gap:12px;align-items:center}.link-preview footer input{flex:1;accent-color:#3d83d8}.link-preview footer span{white-space:nowrap}.timeout{font-size:12px;margin-top:16px}.health-list{display:grid;gap:9px;margin-top:15px;max-height:440px;overflow:auto}.health-list article{display:grid;grid-template-columns:1fr auto;gap:7px;padding:10px;border:1px solid #e4e9f0;border-radius:7px;font-size:11px}.health-list small{grid-column:1/-1;color:#8893a3}.good{color:#218a69}.link-error,.link-message{margin:8px 16px;padding:10px;font-size:12px;border-radius:7px;background:#fff3f0;color:#b34740}.link-message{background:#f0f8f5;color:#337e65}.btn{padding:8px 12px;border:1px solid #d0dcec;border-radius:8px;background:white;color:#34619b;font-size:12px;cursor:pointer}.btn-primary{background:#2868eb;border-color:#2868eb;color:white}.btn:disabled{opacity:.5;cursor:default}@media(max-width:1100px){.animation-link{grid-template-columns:175px minmax(0,1fr)}.link-content{grid-template-columns:270px minmax(0,1fr)}}@media(max-width:850px){.animation-link{grid-template-columns:1fr}.link-device-list{display:flex;max-height:100px}.link-device-list button{flex:0 0 170px}.link-content{grid-template-columns:1fr}.link-config{border-right:0}.link-preview{min-height:420px}}
</style>
